PROGRAM ST_C02_FLERSTATION
VAR
    steg1 : INT := 1;
    steg2 : INT := 0;
    steg3 : INT := 0;
    steg4 : INT := 0;
    tmr1  : TON;
    tmr2  : TON;
    tmr3  : TON;
    tmr4  : TON;
END_VAR

IF NOT EMG_OK THEN
    ST370_STA_DONE := FALSE;
    ST370_HS_REQ   := FALSE;
    ST380_STA_DONE := FALSE;
    ST380_HS_RST   := FALSE;
    ST390_STA_DONE := FALSE;
    ST390_HS_REQ   := FALSE;
    ST400_STA_DONE := FALSE;
    ST400_HS_RST   := FALSE;
    steg1 := 0;
    steg2 := 0;
    steg3 := 0;
    steg4 := 0;
ELSE
    IF steg1 = 0 AND EMG_OK THEN
        steg1 := 1;
    END_IF;

    tmr1(IN := (steg1 = 1), PT := T#18s);
    IF tmr1.Q THEN
        steg1 := 2;
    END_IF;

    IF steg1 = 2 THEN
        ST370_STA_DONE := TRUE;
        ST370_HS_REQ := TRUE;
        IF ST380_HS_ACK THEN
            steg1 := 3;
            steg2 := 1;
        END_IF;
    ELSIF steg1 = 3 THEN
        IF ST380_HS_RST THEN
            ST370_HS_REQ := FALSE;
            ST370_STA_DONE := FALSE;
            steg1 := 4;
        END_IF;
    ELSIF steg1 = 4 THEN
        ST370_STA_DONE := FALSE;
        ST370_HS_REQ := FALSE;
    END_IF;

    tmr2(IN := (steg2 = 1), PT := T#24s);
    IF tmr2.Q THEN
        steg2 := 2;
    END_IF;

    IF steg2 = 1 THEN
        ST380_HS_RST := TRUE;
        ST380_STA_DONE := FALSE;
    ELSIF steg2 = 2 THEN
        ST380_HS_RST := FALSE;
        ST380_STA_DONE := TRUE;
        IF ST390_HS_ACK THEN
            steg2 := 3;
            steg3 := 1;
        END_IF;
    ELSIF steg2 = 3 THEN
        ST380_STA_DONE := FALSE;
        ST380_HS_RST := FALSE;
        steg2 := 4;
    END_IF;

    tmr3(IN := (steg3 = 1), PT := T#21s);
    IF tmr3.Q THEN
        steg3 := 2;
    END_IF;

    IF steg3 = 2 THEN
        ST390_STA_DONE := TRUE;
        ST390_HS_REQ := TRUE;
        IF ST400_HS_ACK THEN
            steg3 := 3;
            steg4 := 1;
        END_IF;
    ELSIF steg3 = 3 THEN
        IF ST400_HS_RST THEN
            ST390_HS_REQ := FALSE;
            ST390_STA_DONE := FALSE;
            steg3 := 4;
        END_IF;
    ELSIF steg3 = 4 THEN
        ST390_STA_DONE := FALSE;
        ST390_HS_REQ := FALSE;
    END_IF;

    tmr4(IN := (steg4 = 1), PT := T#26s);
    IF tmr4.Q THEN
        steg4 := 2;
    END_IF;

    IF steg4 = 1 THEN
        ST400_HS_RST := TRUE;
        ST400_STA_DONE := FALSE;
    ELSIF steg4 = 2 THEN
        ST400_HS_RST := FALSE;
        ST400_STA_DONE := TRUE;
    END_IF;
END_IF;
END_PROGRAM

